codeExamples.code:
-- WRONG: returns zero rows, because anything = NULL evaluates to UNKNOWN
SELECT * FROM customers WHERE phone = NULL;

-- CORRECT: IS NULL is the only way to match missing values
SELECT * FROM customers WHERE phone IS NULL;

-- CORRECT: find rows that DO have a phone
SELECT * FROM customers WHERE phone IS NOT NULL;

-- Gotcha: <> 'active' will NOT return rows where status is NULL,
-- because NULL <> 'active' is UNKNOWN, not TRUE
SELECT * FROM customers WHERE status <> 'active';

-- Include NULLs explicitly when that is the intent
SELECT * FROM customers
WHERE status <> 'active' OR status IS NULL;
